166	/**
167	 * Returns true if the user's 'Always Allow' selection for a specific tool
168	 * should trigger a session-wide transition to AUTO_EDIT mode.
169	 */
170	function isAutoEditTransition(
171	  tool: AnyDeclarativeTool,
172	  outcome: ToolConfirmationOutcome,
173	): boolean {
174	  // TODO: This is a temporary fix to enable AUTO_EDIT mode for specific
175	  // tools. We should refactor this so that callbacks can be removed from
176	  // tools.
177	  return (
178	    outcome === ToolConfirmationOutcome.ProceedAlways &&
179	    EDIT_TOOL_NAMES.has(tool.name)
180	  );
181	}
