144	export interface UpdatePolicy {
145	  type: MessageBusType.UPDATE_POLICY;
146	  toolName: string;
147	  persist?: boolean;
148	  persistScope?: 'workspace' | 'user';
149	  argsPattern?: string;
150	  commandPrefix?: string | string[];
151	  mcpName?: string;
152	  allowRedirection?: boolean;
