159	
160	export interface ToolExecutionSuccess<T = unknown> {
161	  type: MessageBusType.TOOL_EXECUTION_SUCCESS;
162	  toolCall: FunctionCall;
163	  result: T;
164	}
165	
166	export interface ToolExecutionFailure<E = Error> {
167	  type: MessageBusType.TOOL_EXECUTION_FAILURE;
168	  toolCall: FunctionCall;
169	  error: E;
170	}
171	
172	export interface QuestionOption {
173	  label: string;
174	  description: string;
175	}
176	
177	export enum QuestionType {
178	  CHOICE = 'choice',
179	  TEXT = 'text',
180	  YESNO = 'yesno',
181	}
182	
183	export interface Question {
184	  question: string;
185	  header: string;
186	  /** Question type: 'choice' renders selectable options, 'text' renders free-form input, 'yesno' renders a binary Yes/No choice. */
187	  type: QuestionType;
188	  /** Selectable choices. REQUIRED when type='choice'. IGNORED for 'text' and 'yesno'. */
189	  options?: QuestionOption[];
190	  /** Allow multiple selections. Only applies when type='choice'. */
191	  multiSelect?: boolean;
192	  /** Placeholder hint text. For type='text', shown in the input field. For type='choice', shown in the "Other" custom input. */
193	  placeholder?: string;
194	  /** Allow the question to consume more vertical space instead of being strictly capped. */
195	  unconstrainedHeight?: boolean;
196	}
197	
198	export interface AskUserRequest {
199	  type: MessageBusType.ASK_USER_REQUEST;
200	  questions: Question[];
201	  correlationId: string;
202	}
203	
204	export interface AskUserResponse {
205	  type: MessageBusType.ASK_USER_RESPONSE;
206	  correlationId: string;
207	  answers: { [questionIndex: string]: string };
208	  /** When true, indicates the user cancelled the dialog without submitting answers */
209	  cancelled?: boolean;
210	}
211	
212	export interface SubagentActivityMessage {
213	  type: MessageBusType.SUBAGENT_ACTIVITY;
214	  subagentName: string;
215	  activity: SubagentActivityItem;
216	}
217	
218	export type Message =
219	  | ToolConfirmationRequest
220	  | ToolConfirmationResponse
221	  | ToolPolicyRejection
222	  | ToolExecutionSuccess
223	  | ToolExecutionFailure
224	  | UpdatePolicy
225	  | AskUserRequest
226	  | AskUserResponse
227	  | ToolCallsUpdateMessage
228	  | SubagentActivityMessage;
