191	/**
192	 * Filters out insecure policy directories (specifically the system policy directory).
193	 * Supplemental admin policy paths are NOT subject to strict security checks as they
194	 * are explicitly provided by the user/administrator via flags or settings.
195	 * Emits warnings if insecure directories are found.
196	 */
197	async function filterSecurePolicyDirectories(
198	  dirs: string[],
199	  systemPoliciesDir: string,
200	): Promise<string[]> {
201	  const results = await Promise.all(
202	    dirs.map(async (dir) => {
203	      const normalizedDir = path.resolve(dir);
204	      const isSystemPolicy = normalizedDir === systemPoliciesDir;
205	
206	      if (isSystemPolicy) {
207	        const { secure, reason } = await isDirectorySecure(dir);
208	        if (!secure) {
209	          const msg = `Security Warning: Skipping system policies from ${dir}: ${reason}`;
210	          emitWarningOnce(msg);
211	          return null;
212	        }
213	      }
214	      return dir;
215	    }),
216	  );
217	
218	  return results.filter((dir): dir is string => dir !== null);
219	}
