    return;
  }

  // Generic Fallback (Shell, Info, etc.)
  await handleStandardPolicyUpdate(
    tool,
    outcome,
    confirmationDetails,
    messageBus,
    persistScope,
    toolInvocation,
    context.config,
  );
}

