/**
 * Compares two persisted rule identifiers (toolName, and where applicable
 * mcpName / commandPrefix / argsPattern) to determine whether they refer to
 * the same rule. Used to update existing rules in-place instead of creating
 * duplicates. The decision, priority and modes are intentionally ignored so
 * that re-approving the same tool refreshes those fields.
 */
function isSameTomlRule(a: TomlRule, b: TomlRule): boolean {
  return (
    a.toolName === b.toolName &&
    a.mcpName === b.mcpName &&
    isSameCommandPrefix(a.commandPrefix, b.commandPrefix) &&
    a.argsPattern === b.argsPattern
  );
}

function isSameCommandPrefix(
  a: string | string[] | undefined,
  b: string | string[] | undefined,
): boolean {
  if (a === b) {
    return true;
  }
  const aArr = a === undefined ? [] : Array.isArray(a) ? a : [a];
  const bArr = b === undefined ? [] : Array.isArray(b) ? b : [b];
  if (aArr.length !== bArr.length) {
    return false;
  }
  return aArr.every((value, index) => value === bArr[index]);
